returning "id", "slug", "status", "merged_into_id", "title_en", "title_np", "occurred_on", "occurred_time", "location", "location_precision", "place_name_en", "place_name_np", "province_id", "district_id", "local_unit_id", "deaths", "injured_total", "created_via", "verification_level", "version", "created_at", "updated_at";
